const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const d=JSON.parse(fs.readFileSync('outputs/dracula-food/food/product-enrichment.json','utf8'));const b=await chromium.launch();const evidence=[];try{for(const src of d.sources.filter(s=>s.fdc_id)){const p=await b.newPage();let data;const responses=[];p.on('response',r=>{if(r.url().includes('/food/'+src.fdc_id))responses.push(r.json().then(j=>{if(j.foodNutrients)data=j}).catch(()=>{}))});const r=await p.goto(src.url,{waitUntil:'networkidle',timeout:30000});await Promise.allSettled(responses);const content=await p.locator('body').innerText();const row={id:src.fdc_id,url:src.url,httpStatus:r.status(),renderedFood:content.includes('FDC')&&content.includes(String(src.fdc_id)),apiCaptured:!!data,comparisons:[]};if(data){const ids={kcal:1008,energy_kj:1062,protein_g:1003,fat_g:1004,saturates_g:1258,carbohydrate_by_difference_g:1005,sugars_g:2000,fibre_g:1079,sodium_mg:1093};const ref=d.products.find(p=>p.nutrition?.reference?.fdc_id===src.fdc_id).nutrition.reference;for(const [key,val] of Object.entries(ref.values)){const raw=data.foodNutrients.find(n=>n.nutrient?.id===ids[key]);row.comparisons.push({key,expected:val,actual:raw?.amount,ok:raw?.amount===val})}}evidence.push(row);console.log(JSON.stringify(row));await p.close()}}finally{fs.writeFileSync('outputs/dracula-food/audit-usda-evidence.json',JSON.stringify(evidence,null,2));await b.close()}})();
